function joieMaximale(cadeaux, capacite) {
  // sac[c] : meilleure joie possible avec une capacité de c
  const sac = new Array(capacite + 1).fill(0);
  for (const [poids, joie] of cadeaux) {
    for (let c = capacite; c >= poids; c--) {
      sac[c] = Math.max(sac[c], sac[c - poids] + joie);
    }
  }
  return sac[capacite];
}

