def joie_maximale(cadeaux, capacite):
    # sac[c] : meilleure joie possible avec une capacité de c
    sac = [0] * (capacite + 1)
    for poids, joie in cadeaux:
        for c in range(capacite, poids - 1, -1):
            sac[c] = max(sac[c], sac[c - poids] + joie)
    return sac[capacite]

