solution.javascript:
function choisirCadeaux(cadeaux, capacite) {
  const n = cadeaux.length;
  // joie[i][c], poids[i][c] : meilleur résultat (joie max, puis poids min) avec les cadeaux i.. et une capacité c
  const joie = [];
  const poids = [];
  for (let i = 0; i <= n; i++) {
    joie.push(new Array(capacite + 1).fill(0));
    poids.push(new Array(capacite + 1).fill(0));
  }
  for (let i = n - 1; i >= 0; i--) {
    const [p, j] = cadeaux[i];
    for (let c = 0; c <= capacite; c++) {
      joie[i][c] = joie[i + 1][c];
      poids[i][c] = poids[i + 1][c];
      if (p <= c) {
        const v = j + joie[i + 1][c - p];
        const w = p + poids[i + 1][c - p];
        if (v > joie[i][c] || (v === joie[i][c] && w < poids[i][c])) {
          joie[i][c] = v;
          poids[i][c] = w;
        }
      }
    }
  }
  const choix = [];
  let reste = capacite;
  for (let i = 0; i < n; i++) {
    const [p, j] = cadeaux[i];
    if (p <= reste && j + joie[i + 1][reste - p] === joie[i][reste] && p + poids[i + 1][reste - p] === poids[i][reste]) {
      choix.push(i);
      reste -= p;
    }
  }
  return choix;
}

